void Backtrack(int start)
{
    result.Add([.. current]);              // kopia stanu
    for (int i = start; i < nums.Length; i++)
    {
        current.Add(nums[i]);              // wybierz
        Backtrack(i + 1);                  // eksploruj
        current.RemoveAt(current.Count - 1); // cofnij
    }
}

